Q: Singleton Instance returns null A: <p>Alternatively, you can store the password using built-in Sqlite database, though I'd still recommend you save it encrypted for max protection. You can do this in 4 steps:</p>
<p>Create an entity object to store the password:</p>
<pre><code>public class Password {
    int password_id; // will be auto-incremented
    String password;

    public Password(int password_id, String password) {
        this.password_id = password_id;
        this.password = password;
    }

    // getter/setters ...
}
</code></pre>
<p>Create a Sqlite utility class:</p>
<pre><code>public class SQLiteDBAdapter {

    protected static final String DATABASE_NAME = &quot;mydb&quot;;
    protected static final int DATABASE_VERSION = 1;

    protected Context context;
    protected static DatabaseHelper mDbHelper;

    public static final String TABLE_PASSWORD = &quot;tbl_password&quot;;
    // columns
    public static final String PASSWORD_ID = &quot;_id&quot;;
    public static final String PASSWORD = &quot;password&quot;;
    // create table string
    private static final String CREATE_TABLE_PASSWORD =
            &quot;CREATE TABLE if not exists &quot; + TABLE_PASSWORD + &quot; ( &quot; +
                    PASSWORD_ID + &quot; INTEGER PRIMARY KEY AUTOINCREMENT, &quot; +
                    PASSWORD + &quot; TEXT NOT NULL);&quot;;

    public SQLiteDBAdapter(Context context) {
      context = context.getApplicationContext();
    }

    public SQLiteDatabase openDb() {
      if (mDbHelper == null) {
          mDbHelper = new DatabaseHelper(mContext);
      }
      return mDbHelper.getWritableDatabase();
    }

    protected static class DatabaseHelper extends SQLiteOpenHelper {
      // -------------------------------------------------------------------------------------------
      public DatabaseHelper(Context context) {
          super(context, DATABASE_NAME, null, DATABASE_VERSION);
      }
      // -------------------------------------------------------------------------------------------
      @Override
      public void onCreate(SQLiteDatabase db) {
          db.execSQL(CREATE_TABLE_PASSWORD);
      }
      // -------------------------------------------------------------------------------------------
      @Override
      public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
          Log.w(TAG, &quot;Upgrading database from version &quot; + oldVersion + &quot; to &quot; +
                  newVersion + &quot;, which will destroy all old data&quot;);
          db.execSQL(&quot;DROP TABLE IF EXISTS routes&quot;);
          onCreate(db);
      }
    }
}
</code></pre>
<p>Extend a Sqlite object to manipulate the table (CRUD operations):</p>
<pre><code>public class PasswordDbAdapter extends SQLiteDBAdapter {

    private SQLiteDatabase db;

    // these are column corresponding indices
    public static final int INDEX_PASSWORD_ID = 0;  // an auto-increment
    public static final int INDEX_PASSWORD = 1;

    public PasswordDbAdapter(Context context) {
        super(context);
    }

    public void addPassword(String password) {
        db = openDb();
        ContentValues values = new ContentValues();
        values.put(PASSWORD, password);
        db.insert(TABLE_PASSWORD, null, values);
    }

    public void updatePassword(String password) {
        db = openDb();
        ContentValues values = new ContentValues();
        values.put(PASSWORD, password);
        db.update(TABLE_PASSWORD, values, null);
    }

    public void deletePassword() {
        db = openDb();
        db.delete(TABLE_PASSWORD, null, null);
    }

    public boolean isEmpty() {
        db = openDb();
        boolean empty = true;
        Cursor cur = db.rawQuery(&quot;SELECT COUNT(*) FROM &quot; + TABLE_PASSWORD, null);
        if (cur != null &amp;&amp; cur.moveToFirst()) {
            empty = (cur.getInt (0) == 0);
        }
        cur.close();
        return empty;
    }

    public Password fetchPassword() {   // ok because there's only one password record
        db = openDb();
        Cursor cursor = db.query(TABLE_PASSWORD, new String[]{PASSWORD_ID, PASSWORD},
                null, null, null, null, null, null);
        if (cursor != null &amp;&amp;
            cursor.moveToFirst()) {
            return new Password(
                    cursor.getString(INDEX_PASSWORD_ID),
                    cursor.getInt(INDEX_PASSWORD));
        }
        return null;
    }
}
</code></pre>
<p>Finally, save/update/retrieve the password as desired:</p>
<pre><code>public class MainActivity extends AppCompatActivity {
    private PasswordDbAdapter passwordDB; 
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        ... 
        // initialize the password db
        passwordDB = new PasswordDbAdapter(this);

        // check if password record exists
        if (passwordDB.isEmpty() {
            // save a new copy
            passwordDB.addPassword(&quot;the_password&quot;); // more secure if it is saved encrypted
        } else {
            // update it
            passwordDB.updatePassword(&quot;the_password&quot;);
        }

    }
    ...
    public String fetchPassword() {
        return passwordDB.fetchPassword();  // or first decrypt it, then return it
    }
}
</code></pre>

Q: Most efficient way to find next increment in a big number A: <p>You can do it in logarithmic time using <a href="http://docs.oracle.com/javase/6/docs/api/java/util/TreeMap.html#floorEntry(K)" rel="nofollow noreferrer"><code>floorEntry</code></a> by finding lower-bound.</p>
<pre><code>private TreeMap&lt;Integer, Integer&gt; aboveNbr_increment_map;

private Integer getIncrementValueAboveNbr(int nbr) {

    Entry&lt;Integer, Integer&gt; entry = aboveNbr_increment_map.floorEntry(nbr);

    if (entry != null) {
        return nbr + entry.getValue();
    }

    return aboveNbr_increment_map.get(aboveNbr_increment_map.firstKey());
}
</code></pre>
<p>Before this store the key-value in <code>TreeMap</code> like this:</p>
<pre><code>aboveNbr_increment_map.put(x + 1, xx);
aboveNbr_increment_map.put(y + 1, yy);
</code></pre>
<p>You need to store <code>x + 1</code> instead of <code>x</code> because <code>floorEntry</code> returns the greatest key less than or equal to the given key. And here we are incrementing when <code>nbr</code> value is <code>&gt; x</code>.</p>
<p>Hope it helps!</p>

Q: How do i save data when user is logged in the app in Android? A: <p>You can use the same table, like this:</p>
<p>Your entity object:</p>
<pre><code>public class UserInfo {
    int id; // will be auto-incremented
    String name;
    String password;

    public UserInfo(int id, String name, String password) {
        this.id = id;
        this.name = name;
        this.password = password;
    }

    // getter/setters ...
}
</code></pre>
<p>Your Sqlite utility class (note you can add more tables, as you wish):</p>
<pre><code>public class SQLiteDBAdapter {

    protected static final String DATABASE_NAME = &quot;mydb&quot;;
    protected static final int DATABASE_VERSION = 1;

    protected Context context;
    protected static DatabaseHelper mDbHelper;

    public static final String TABLE_USER_INFO = &quot;tbl_userinfo&quot;;
    // columns
    public static final String USER_ID = &quot;_id&quot;;
    public static final String NAME = &quot;name&quot;;
    public static final String PASSWORD = &quot;password&quot;;
    // create table string
    private static final String CREATE_TABLE_USER_INFO =
            &quot;CREATE TABLE if not exists &quot; + TABLE_USER_INFO + &quot; ( &quot; +
                    USER_ID + &quot; INTEGER PRIMARY KEY AUTOINCREMENT, &quot; +
                    NAME + &quot; TEXT NOT NULL, &quot; +
                    PASSWORD + &quot; TEXT NOT NULL);&quot;;

    public SQLiteDBAdapter(Context context) {
      context = context.getApplicationContext();
    }

    public SQLiteDatabase openDb() {
      if (mDbHelper == null) {
          mDbHelper = new DatabaseHelper(mContext);
      }
      return mDbHelper.getWritableDatabase();
    }

    protected static class DatabaseHelper extends SQLiteOpenHelper {
      // -------------------------------------------------------------------------------------------
      public DatabaseHelper(Context context) {
          super(context, DATABASE_NAME, null, DATABASE_VERSION);
      }
      // -------------------------------------------------------------------------------------------
      @Override
      public void onCreate(SQLiteDatabase db) {
          db.execSQL(CREATE_TABLE_USER_INFO);
      }
      // -------------------------------------------------------------------------------------------
      @Override
      public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
          Log.w(TAG, &quot;Upgrading database from version &quot; + oldVersion + &quot; to &quot; +
                  newVersion + &quot;, which will destroy all old data&quot;);
          db.execSQL(&quot;DROP TABLE IF EXISTS routes&quot;);
          onCreate(db);
      }
    }
}
</code></pre>
<p>Extend a Sqlite object to manipulate the table (CRUD operations):</p>
<pre><code>public class UserInfoDbAdapter extends SQLiteDBAdapter {

    private SQLiteDatabase db;

    // these are column corresponding indices
    public static final int INDEX_ID = 0;  // an auto-increment
    public static final int INDEX_NAME = 1;
    public static final int INDEX_PASSWORD = 2;

    public UserInfoDbAdapter(Context context) {
        super(context);
    }

    public void add(String name, String password) {
        db = openDb();
        ContentValues values = new ContentValues();
        values.put(NAME, name);
        values.put(PASSWORD, password);
        db.insert(TABLE_USER_INFO, null, values);
    }

    public void update(String name, String password) {
        db = openDb();
        ContentValues values = new ContentValues();
        values.put(NAME, name);
        values.put(PASSWORD, password);
        db.update(TABLE_USER_INFO, values, null);
    }

    public void deleteAll() {
        db = openDb();
        db.delete(TABLE_USER_INFO, null, null);
    }

    public boolean isEmpty() {
        db = openDb();
        boolean empty = true;
        Cursor cursor = db.rawQuery(&quot;SELECT COUNT(*) FROM &quot; + TABLE_USER_INFO, null);
        if (cursor != null &amp;&amp; cursor.moveToFirst()) {
            empty = (cursor.getInt (0) == 0);
        }
        cursor.close();
        return empty;
    }

    public UserInfo fetchRecord() { // only one record to fetch
        db = openDb();
        Cursor cursor = db.query(TABLE_USER_INFO, new String[]{USER_ID, NAME, PASSWORD},
                null, null, null, null, null, null);
        if (cursor != null &amp;&amp;
            cursor.moveToFirst()) {
            return new UserInfo(
                    cursor.getInt(INDEX_ID),
                    cursor.getString(INDEX_NAME),
                    cursor.getInt(INDEX_PASSWORD));
        }
        return null;
    }
}
</code></pre>
<p>Finally, add/update/delete/fetch user record as desired:</p>
<pre><code>public class MainActivity extends AppCompatActivity {
    private UserInfoDbAdapter userDB; 
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        ... 
        // initialize user db
        userDB = new UserInfoDbAdapter(this);

        // add user if table is empty
        if (userDB.isEmpty() {
            // add user
            userDB.add(nameTextView.getText().toString(), passwordTextView.getText().toString());
// note it's always more secure to store encrypted password, rather than plain text.
        } else {
            // update
            userDB.update(nameTextView.getText().toString(), passwordTextView.getText().toString());
        }

    }
    ...
    // fetch record
    public UserInfo fetchRecord() {
        return userDB.fetchRecord();
    }
}
</code></pre>

Q: When can the address of immediate function be used as template argument? A: <p>As for the problem you’re trying to solve, one workaround is a zero-cost wrapper class:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;concepts&gt;

consteval void foo() noexcept {}
class FooWrapper {
    public:

    static consteval void operator()() noexcept
    {
        foo();
    }
};

template &lt;std::invocable&lt;&gt; F&gt;
struct  A{ int i = 1; };

consteval auto bar() {
    return A&lt;FooWrapper&gt;{};
}
</code></pre>
<p>Or just make your <code>consteval</code> function the <code>static consteval operator()</code> of a class to begin with, so you can invoke it the same way and have a functor type to use.</p>
<p>Alternatively, if you declare <code>foo</code> as a <code>constexpr</code> lambda, GCC, Clang, ICX  and MSVC all accept:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;concepts&gt;
#include &lt;type_traits&gt;
#include &lt;utility&gt;


// A somewhat-overengineered demo class.
template &lt;std::regular_invocable&lt;&gt; F&gt;
struct  A{
    [[no_unique_address]] F functor;

    public:

    consteval A()
        requires std::is_default_constructible_v&lt;F&gt;
     = default;

// Having noexcept on a consteval function is an effect of adding the consteval specifier later.
    explicit consteval A(const F&amp; f) noexcept(std::is_nothrow_copy_constructible_v&lt;F&gt;)
        requires std::is_copy_constructible_v&lt;F&gt;
    : functor(f)
    {}

    explicit consteval A(F&amp;&amp; f) noexcept(std::is_nothrow_move_constructible_v&lt;F&gt;)
        requires std::is_move_constructible_v&lt;F&gt;
    : functor(std::move(f))
    {}

    consteval void fn() const noexcept(std::is_nothrow_invocable_v&lt;F&gt;)
    {
        functor();
    }
};


consteval void foo() noexcept {}
constexpr auto baz = [] consteval noexcept { foo(); };


consteval auto bar() {
    return A&lt;decltype(baz)&gt;{};
}


int main()
{
    constexpr auto result = bar();
    result.fn();
    return 0;
}
</code></pre>
<p>If you need an API that can accept any of these options or arbitrary functions as callbacks, wrap the callback in a <code>std::move_only_function&lt;void()&gt;</code>, or <code>std::function</code> if you need to make copies of the callback object.</p>

Q: Dynamic Javascipt array manipulation A: <p>You could simply take <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Object/groupBy" rel="nofollow noreferrer"><code>Object.groupBy</code></a> with <code>age</code> as grouping parameter for the first step</p>
<pre class="lang-js prettyprint-override"><code>// groupBy
{
    20: [
        { name: &quot;Henry&quot;, age: 20 },
        { name: &quot;Max&quot;, age: 20 }
   ],
   21: [
       { name: &quot;Alice&quot;, age: 21 },
       { name: &quot;Jane&quot;, age: 21 }
   ]
}
</code></pre>
<p>and then map new objects with a single <code>age</code> property and mapped <code>name</code>.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const
    data = [{ name: 'Alice', age: 21 }, { name: 'Henry', age: 20 }, { name: 'Max', age: 20 }, { name: 'Jane', age: 21 }],
    result = Object
        .values(Object.groupBy(data, ({ age }) =&gt; age))
        //.map(a =&gt; ({ age: a[0].age, name: a.map(({ name }) =&gt; name) }));

console.log(result);</code></pre>
